INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(16101, 'Proverbs 24:10', 'Proverbs', 24, 10, '&nbsp;کۀ تۀ په سخت وخت همت بائيلې، نو تۀ بيا ډېر کمزورے انسان يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16102, 'Proverbs 24:11', 'Proverbs', 24, 11, '&nbsp;د هغه کس په بچ کولو کښې سستى مۀ کوه څوک چې مرګ ته روان کړے شوے وى، او هغه حلالولو ته مۀ پرېږده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16103, 'Proverbs 24:12', 'Proverbs', 24, 12, '&nbsp;کۀ تاسو چرې وايئ، ”مونږ ته خو د دې په حقله څۀ عِلم نشته دے،“ نو هغه څوک چې د زړونو په سوچونو خبر دے نو دا به معلوم نۀ کړى څۀ؟ هغه څوک چې ستا د ژوندون خيال ساتى په دې نۀ پوهيږى څۀ؟ هغه به هر هغه چا ته د خپل عمل په مطابق بدله ورنۀ کړى څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16104, 'Proverbs 24:13', 'Proverbs', 24, 13, '&nbsp;زما زويه، شهد خوره، ځکه چې دا ښۀ څيز دے، د ګبين د شهدو خوند خوږ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16105, 'Proverbs 24:14', 'Proverbs', 24, 14, '&nbsp;نو په دې يقين وکړه چې حِکمت هم دغه شان ستا د ځان دپاره خوږ دے، کۀ چرې تۀ يې بيامومې نو دا ستا د راتلونکى ژوند دپاره اُميد دے، او دا اُميد به هيڅکله ستا نه اخوا نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16106, 'Proverbs 24:15', 'Proverbs', 24, 15, '&nbsp;د بدکارانو غوندې مۀ جوړېږه څوک چې د صادقانو د کور خلاف په انتظار کښې ناست وى، او د هغوئ په کورونو حمله مۀ کوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16107, 'Proverbs 24:16', 'Proverbs', 24, 16, '&nbsp;کۀ څۀ هم چې صادق انسان اووۀ ځله راپرېوځى هغه دوباره راپاڅى، خو د بدکاره دپاره يو افت بس دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16108, 'Proverbs 24:17', 'Proverbs', 24, 17, '&nbsp;هرکله چې ستا دشمن راپرېوځى نو په هغۀ باندې خوشحالى مۀ کوه، او کله چې هغه تيندک وخورى نو په هغۀ باندې خپل زړۀ مۀ خوشحالوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16109, 'Proverbs 24:18', 'Proverbs', 24, 18, '&nbsp;نو مالِک خُدائ به ستا دا خوشحالى وګورى او هغه به ستا نه نارضا شى او د هغۀ نه به خپل غضب اخوا کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16110, 'Proverbs 24:19', 'Proverbs', 24, 19, '&nbsp;د بدکارانو په وجه مۀ پرېشانه کېږه، او مۀ د هغوئ سره حسد کوه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16111, 'Proverbs 24:20', 'Proverbs', 24, 20, '&nbsp;ځکه چې د بدعمله سره د آئنده اُميد نشته، او د هغوئ ډيوه په مړه کېدو ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16112, 'Proverbs 24:21', 'Proverbs', 24, 21, '&nbsp;زما زويه، د مالِک خُدائ او د بادشاه نه يرېږه، او د باغيانو سره ملګرتيا مۀ کوه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16113, 'Proverbs 24:22', 'Proverbs', 24, 22, '&nbsp;ځکه چې دا دواړه به ناڅاپه تباهى ورنازله کړى نو څوک د دې اندازه لګولے شى چې څۀ قسمه تباهى به په دوئ راولېږى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16114, 'Proverbs 24:23', 'Proverbs', 24, 23, '&nbsp;هوښياران هم داسې وائى، د عدالت کولو په وخت کښې د چا طرفدارى په کار نۀ ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16115, 'Proverbs 24:24', 'Proverbs', 24, 24, '&nbsp;هر هغه څوک چې يو ګناه ګار ته ووائى چې، ”تۀ بې‌ګناه يې،“ ټول قوم به په دۀ باندې لعنت ووائى او قومونه به يې رسوا کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16116, 'Proverbs 24:25', 'Proverbs', 24, 25, '&nbsp;خو هغه څوک چې مجرم رټى، نو ډېر برکتونه به په هغوئ نازل شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16117, 'Proverbs 24:26', 'Proverbs', 24, 26, '&nbsp;څوک چې هر وخت رښتينے جواب درکوى هغه اصلى دوست دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16118, 'Proverbs 24:27', 'Proverbs', 24, 27, '&nbsp;خپل بهرنى کارونه اول ختم کړه او خپله د کروندې زمکه تياره کړه، د دې نه وروستو خپل کور جوړوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16119, 'Proverbs 24:28', 'Proverbs', 24, 28, '&nbsp;د ثبوت نه بغېر دې د خپل ګاونډى خِلاف ګواهى مۀ ورکوه، او د هغۀ په حقله د دروغو خبرې مۀ کوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16120, 'Proverbs 24:29', 'Proverbs', 24, 29, '&nbsp;داسې مۀ وايه، ”هغۀ چې ما سره څۀ کړى دى نو زۀ به هم هغه شان ورسره وکړم، او زۀ به ترې نه خپل بدل واخلم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16121, 'Proverbs 24:30', 'Proverbs', 24, 30, '&nbsp;زۀ د يو ناراسته سړى په پټى تير شوم او د کم عقل د انګورو باغ مې وکتلو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16122, 'Proverbs 24:31', 'Proverbs', 24, 31, '&nbsp;په هر ځائ کښې ازغى راختلى وُو، او زمکه ټوله په ډيله باندې ډکه وه، او د کاڼو دېوالونه يې راغورزېدلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16123, 'Proverbs 24:32', 'Proverbs', 24, 32, '&nbsp;ما چې څۀ وليدل نو په خپل زړۀ کښې مې ورباندې سوچ وکړو، او چې څۀ مې وليدل د هغې نه مې سبق زده کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16124, 'Proverbs 24:33', 'Proverbs', 24, 33, '&nbsp;کۀ يو سړے وائى چې، ”لږ به اودۀ شم، لږې به سترګې پټې کړم، لږ به خپل لاسونه راغونډ کړم چې دمه شم،“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16125, 'Proverbs 24:34', 'Proverbs', 24, 34, '&nbsp;خو بيا غريبى به لکه د يو ډاکو په شان په هغۀ باندې ورټوپ کړى، او نيستى به لکه د وسله بند انسان په شان هغه راګېر کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16126, 'Proverbs 25:1', 'Proverbs', 25, 1, '&nbsp;دا د سليمان نور متلونه دى، کوم چې د حزقياه کاتبانو د يهوداه بادشاه راجمع کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16127, 'Proverbs 25:2', 'Proverbs', 25, 2, '&nbsp;دا د خُدائ پاک شان دے چې يوه معامله په راز کښې ساتى، خو د يوې مسئلې ښکاره کول د بادشاه عزت څرګندوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16128, 'Proverbs 25:3', 'Proverbs', 25, 3, '&nbsp;څومره چې آسمانونه اوچت او زمکه ژوره ده، هم دغه شان د بادشاهانو زړونه نامعلوم دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16129, 'Proverbs 25:4', 'Proverbs', 25, 4, '&nbsp;د سپينو زرو نه ملاوټ لرې کړه ترڅو زرګر ترې نه يو ښائسته لوښے جوړ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16130, 'Proverbs 25:5', 'Proverbs', 25, 5, '&nbsp;نو دغه شان د بادشاه د حضور نه بدکاران لرې کړه، نو د هغۀ حکومت به د صداقت په وجه قائم وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16131, 'Proverbs 25:6', 'Proverbs', 25, 6, '&nbsp;د بادشاه په حضور کښې د خپل ځان لوئى مۀ کوه، او مۀ د لويو خلقو په ځائ کښې وړاندې کښېنه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16132, 'Proverbs 25:7', 'Proverbs', 25, 7, '&nbsp;دا به ښۀ وى چې هغه تا راوغواړى چې، ”دلته راشه،“ او نۀ دا چې هغه تا د مشرانو په وړاندې بې‌عزته کړى او ښکته دې کښېنوى. څۀ چې تا په خپلو سترګو ليدلى وى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16133, 'Proverbs 25:8', 'Proverbs', 25, 8, '&nbsp;نو هغه په عدالت کښې په تېزۍ سره مۀ وړاندې کوه، نو تۀ به په آخر کښې څۀ کوې کۀ چرې ستا ګاونډى تا ملامته کړى او بيا دې وشرموى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16134, 'Proverbs 25:9', 'Proverbs', 25, 9, '&nbsp;کۀ تۀ خپل ګاونډى سره په يوه مقدمه کښې بحث کوې، نو په هغه وخت کښې د بل انسان راز ورته مۀ څرګندوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16135, 'Proverbs 25:10', 'Proverbs', 25, 10, '&nbsp;او کۀ چرې هغه دا واورى او تا وشرموى، نو بيا به تۀ خپله دا بدنامى هيڅکله ختمه نۀ کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16136, 'Proverbs 25:11', 'Proverbs', 25, 11, '&nbsp;په ځائ خبره داسې وى لکه چې د سپينو زرو په لوښى کښې د سرو زرو مڼه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16137, 'Proverbs 25:12', 'Proverbs', 25, 12, '&nbsp;د يو هوښيار سړى تنبيه د هغه غوږ دپاره څوک اورېدلے شى لکه د سرو زرو والۍ او يا د سوچه سرو زرو کالى په شان ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16138, 'Proverbs 25:13', 'Proverbs', 25, 13, '&nbsp;يو باورى پېغام وړونکے لکه د لو په موسم کښې د واورې د يخوالى په شان دے د هغه چا دپاره څوک چې هغه استوى، او هغه د خپل مالِک زړۀ يخوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16139, 'Proverbs 25:14', 'Proverbs', 25, 14, '&nbsp;لکه د هغه وريځ او هوا په شان چې باران نۀ ورَوى، هغه څوک دے چې د تُحفو ورکولو وعده کوى او بيا ‎يې نۀ ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16140, 'Proverbs 25:15', 'Proverbs', 25, 15, '&nbsp;د صبر په وجه مشر هم قائليږى، او يوه نرمه خبره هډُوکى هم ماتوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16141, 'Proverbs 25:16', 'Proverbs', 25, 16, '&nbsp;کۀ چرې تا ته شهد مِلاو شى نو ضرورت نه زيات مۀ خوره، په زيات خوړلو به دا قے کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16142, 'Proverbs 25:17', 'Proverbs', 25, 17, '&nbsp;د خپلو ګاونډيانو کور ته کم ورځه، کۀ چرې تۀ ډېر ورځې نو کېدے شى چې ستا نه نفرت شروع کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16143, 'Proverbs 25:18', 'Proverbs', 25, 18, '&nbsp;څوک چې د خپل ګاونډى خلاف د دروغو ګواهى ورکوى هغوئ لکه د لَوړ، يا تُورې يا د تېرۀ غشى غوندې خطرناک وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16144, 'Proverbs 25:19', 'Proverbs', 25, 19, '&nbsp;لکه په خراب غاښ خوړل يا په ګوډه پښه تلل کول داسې دى لکه په سخت وخت کښې چې په ناباوره کس توکل کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16145, 'Proverbs 25:20', 'Proverbs', 25, 20, '&nbsp;يو خفه کس ته چې څوک د خوشحالۍ سندرې وائى، نو هغه به داسې وى لکه چې د يو کس نه په يخ موسم کښې څادر اخوا کړى، او يا سرکه د هغۀ په زخم واړوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16146, 'Proverbs 25:21', 'Proverbs', 25, 21, '&nbsp;کۀ ستا دشمنان اوږى وى، نو هغوئ له خوراک ورکړه، کۀ چرې هغوئ تږى وى، نو هغوئ له اوبۀ ورکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16147, 'Proverbs 25:22', 'Proverbs', 25, 22, '&nbsp;نو په داسې کولو سره تۀ د هغۀ په سر باندې به بل سکارۀ واړوې، او مالِک خُدائ به تا له اجر درکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16148, 'Proverbs 25:23', 'Proverbs', 25, 23, '&nbsp;لکه څنګه چې د شمال هوا باران راولى، نو دغه شان پشى شا خبرې کول د خلقو مخ د غصې نه تک سور کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16149, 'Proverbs 25:24', 'Proverbs', 25, 24, '&nbsp;دا بهتره ده چې د کوټې دپاسه په يو ګوټ کښې ځانله ژوند کوې نه چې په کور کښې د ژبه ورې ښځې سره اوسېږې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16150, 'Proverbs 25:25', 'Proverbs', 25, 25, '&nbsp;لکه يخې اوبۀ چې د ستړى زړۀ دپاره ښې وى نو دغه شان يو ښۀ زېرے د لرې مُلک نه دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16151, 'Proverbs 25:26', 'Proverbs', 25, 26, '&nbsp;کۀ يو صادق انسان د بدکاره په سازش کښې راشى نو هغه بيا د ګنده چينې او يا خراب کوهى په شان وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16152, 'Proverbs 25:27', 'Proverbs', 25, 27, '&nbsp;دا ښۀ نۀ دے چې زيات شهد وخوړلے شې، او يا د ځان دپاره د حد نه زيات عزت وغواړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16153, 'Proverbs 25:28', 'Proverbs', 25, 28, '&nbsp;څوک چې خپل نفس نۀ شى قابو کولے هغه د هغه ښار په شان بې‌وسه دے چې دېوالونه يې غورزېدلى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16154, 'Proverbs 26:1', 'Proverbs', 26, 1, '&nbsp;لکه څنګه چې په اوړى کښې واوره يا د لو په موسم کښې باران نامناسب وى، دغه شان د کم عقل انسان عزت کول هم دومره نامناسبه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16155, 'Proverbs 26:2', 'Proverbs', 26, 2, '&nbsp;لکه څنګه چې چڼچڼه اخوا ديخوا الوځى او يا چې طوطاګرکے چکرې وهى او په ځائ نۀ کښېنى، دغه شان نامناسبه ښيرا کول د چا په سر نۀ کښېنى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16156, 'Proverbs 26:3', 'Proverbs', 26, 3, '&nbsp;لکه څنګه چې د آس دپاره چابک، د خر دپاره واګې وى نو هم دغه شان د کم عقل د ملا دپاره چوکه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16157, 'Proverbs 26:4', 'Proverbs', 26, 4, '&nbsp;کم عقل ته د هغۀ د کم عقلتوب په مطابق جواب مۀ ورکوه، ګنې تۀ به هم د هغۀ په شان شې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16158, 'Proverbs 26:5', 'Proverbs', 26, 5, '&nbsp;د کم عقل سوال ته کم عقل جواب ورکوه ځکه چې هغه خپل ځان هوښيار ونۀ ګڼى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16159, 'Proverbs 26:6', 'Proverbs', 26, 6, '&nbsp;د يو کم عقل په لاس پېغام استول داسې دى لکه انسان چې په خپله ځان نه پښې پرې کړى او يا زهر وڅښى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16160, 'Proverbs 26:7', 'Proverbs', 26, 7, '&nbsp;د کم عقل په خولې متل داسې وى لکه څنګه چې د يو ګوډ پښه بې‌کاره وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16161, 'Proverbs 26:8', 'Proverbs', 26, 8, '&nbsp;کم عقل ته عزت ورکول داسې وى لکه څوک چې ليندې پورې کاڼے وتړى او ګزار پرې نۀ شى کولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16162, 'Proverbs 26:9', 'Proverbs', 26, 9, '&nbsp;لکه څنګه چې د ازغو بوټى د يو شرابى په لاس کښې وى دغه شان يو متل د کم عقل په خولۀ کښې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16163, 'Proverbs 26:10', 'Proverbs', 26, 10, '&nbsp;هغه څوک چې کم عقل او يا لوفر ته کار ورکړى هغه لکه د هغه غشى ويشتونکى په شان وى چې هر څوک پرې ولى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16164, 'Proverbs 26:11', 'Proverbs', 26, 11, '&nbsp;لکه څنګه چې يو سپے خپلې اولټيانې دوباره څټى دغه شان کم عقل خپل کم عقلتوب بار بار کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16165, 'Proverbs 26:12', 'Proverbs', 26, 12, '&nbsp;تاسو داسې سړے ليدلے دے چې هغۀ ته خپل ځان هوښيار ښکارى؟ خو د دۀ نه زيات اُميد د يو کم عقل دپاره وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16166, 'Proverbs 26:13', 'Proverbs', 26, 13, '&nbsp;ناراسته وائى چې، ”په لار کښې زمرے دے، خطرناک زمرے په کوڅو کښې ګرځى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16167, 'Proverbs 26:14', 'Proverbs', 26, 14, '&nbsp;لکه څنګه چې دروازه په خپلو قبضو تاويږى، دغه شان ناراسته په خپل کټ کښې اوړى راوړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16168, 'Proverbs 26:15', 'Proverbs', 26, 15, '&nbsp;ناراسته خپل لاس تالى ته وراوږدوى، خو هغه دومره ناراسته وى چې واپس يې خپلې خولې ته نۀ راوړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16169, 'Proverbs 26:16', 'Proverbs', 26, 16, '&nbsp;ناراسته خپل ځان د اووۀ هوښيار سړو نه هم زيات هوښيار ګڼى څوک چې په حِکمت سره جواب ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16170, 'Proverbs 26:17', 'Proverbs', 26, 17, '&nbsp;لکه څوک چې يو کوڅه ډب سپے د غوږونو نه راونيسى د هغه چا په شان دے چې د بل چا په بحث کښې ځان شامل کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16171, 'Proverbs 26:20', 'Proverbs', 26, 20, '&nbsp;د پوکى نه بغېر اور مړ کيږى، او د غېبت نه بغېر جنګ ختميږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16172, 'Proverbs 26:21', 'Proverbs', 26, 21, '&nbsp;لکه څنګه چې سکارۀ بليږى او لکه څنګه چې لرګى لمبې کوى، نو دغه شان د جنګ د تودولو دپاره جنګ مار سړے وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16173, 'Proverbs 26:22', 'Proverbs', 26, 22, '&nbsp;د غېبت کوونکى خبرې لکه د خوندور خوراک په شان وى، دا بلکل د سړى دننه بدن ته کوزيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16174, 'Proverbs 26:23', 'Proverbs', 26, 23, '&nbsp;نرمې خبرې شرير زړۀ پټوى لکه څنګه چې په خاورين لوښى باندې رنګ روغن وشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16175, 'Proverbs 26:24', 'Proverbs', 26, 24, '&nbsp;کينه ناک انسان په خوږو خبرو کولو خپل نفرت پټوى، خو په زړۀ کښې يې کينه ساتلې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16176, 'Proverbs 26:25', 'Proverbs', 26, 25, '&nbsp;کۀ څۀ هم چې د هغۀ خبرې خوږې وى خو په هغوئ يقين مۀ کوه، ځکه چې د هغۀ زړۀ د رنګارنګ حرام کاريو نه ډک وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16177, 'Proverbs 26:26', 'Proverbs', 26, 26, '&nbsp;کۀ د هغۀ بدنېتى د هغۀ په چل وَل کښې پټه وى، خو بيا هم د هغۀ شرارت هر چا ته ښکاره شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16178, 'Proverbs 26:27', 'Proverbs', 26, 27, '&nbsp;کۀ يو انسان بل چا ته کنده کنى نو هغه په خپله په کښې ورغورزيږى، او کۀ يو انسان په بل چا کاڼے رغړوى هغه کاڼے به په خپله په دۀ باندې راورغړيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16179, 'Proverbs 26:28', 'Proverbs', 26, 28, '&nbsp;د بل چا په حقله دروغ وئيل د هغۀ نه نفرت کول دى، او د خوشامندۍ خبرې تباهى راولى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16180, 'Proverbs 27:1', 'Proverbs', 27, 1, '&nbsp;د سبا په حقله لافې مۀ کوئ، ځکه چې چا ته هم پته نشته چې سبا به څۀ کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16181, 'Proverbs 27:2', 'Proverbs', 27, 2, '&nbsp;دا به ښۀ وى چې نور خلق ستا صِفت وکړى، نه چې تۀ په خپله د خپل ځان صِفت کوې، او دا به ښۀ وى چې نابلده خلق ستا ښۀ ووائى نه چې تۀ په خپله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16182, 'Proverbs 27:3', 'Proverbs', 27, 3, '&nbsp;کاڼے دروند وى شګې درنې وى، خو د يو کم عقل تنګول د دې دواړو نه زيات درانۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16183, 'Proverbs 27:4', 'Proverbs', 27, 4, '&nbsp;قهر خو ظالم دے او غضب انسان چخڼى کوى خو د حسد په وړاندې څوک ټينګېدے شى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16184, 'Proverbs 27:5', 'Proverbs', 27, 5, '&nbsp;څرګنده رټنه د پټې مينې نه ښۀ ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16185, 'Proverbs 27:6', 'Proverbs', 27, 6, '&nbsp;د دوست رټنه د هغۀ د مينې اظهار دے، خو د دشمن ښکلول سراسر دوکه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16186, 'Proverbs 27:7', 'Proverbs', 27, 7, '&nbsp;څوک چې موړ وى هغه شهد هم د پښو لاندې کوى، خو د اوږى دپاره تريخ خوراک هم خوږ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16187, 'Proverbs 27:8', 'Proverbs', 27, 8, '&nbsp;لکه څنګه چې يوه مرغۍ د خپلې جالې نه ورکه شوې وى د هغه چا په شان وى لکه څوک د خپل کور نه په صحرا شوى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16188, 'Proverbs 27:9', 'Proverbs', 27, 9, '&nbsp;لکه څنګه چې عطر او خوشبو د انسان زړۀ خوشحالوى، هم دغه شان ښې مشورې دوستان خوشحالوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16189, 'Proverbs 27:10', 'Proverbs', 27, 10, '&nbsp;خپل دوستان او د خپل پلار دوستان مۀ هېروه، د خپل ورور کور ته مۀ ځه کله چې په تا څۀ مصيبت راشى. ستا نزدې ګاونډى د لرې ورور نه ښۀ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16190, 'Proverbs 27:11', 'Proverbs', 27, 11, '&nbsp;زما زويه، هوښيار اوسه او زما زړۀ خوشحاله کړه، نو بيا به زۀ هر هغه چا ته جواب ورکولے شم څوک چې ما ته سپک ګورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16191, 'Proverbs 27:12', 'Proverbs', 27, 12, '&nbsp;هوښياران خطره د اول نه وينى او د هغې نه ځان بچ کوى، خو کم عقل پرې ورخلاص وى او بيا په تکليف کښې راګېر شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16192, 'Proverbs 27:13', 'Proverbs', 27, 13, '&nbsp;هر څوک چې د پردى کس د قرض ذمه وارى اخلى نو ضمانت ترې نه واخله، ضمانت ترې نه واخله کۀ چرې دۀ دا کار د پردى کس دپاره کړے وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16193, 'Proverbs 27:14', 'Proverbs', 27, 14, '&nbsp;کۀ چرې څوک سحر د وخته په اوچت آواز سره په خپل ګاونډى سلام واچوى، دا به هغه لکه د کنځلو په شان وګڼى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16194, 'Proverbs 27:15', 'Proverbs', 27, 15, '&nbsp;يوه جګړماره ښځه داسې وى لکه چې په باران کښې د کوټې چت راڅاڅى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16195, 'Proverbs 27:16', 'Proverbs', 27, 16, '&nbsp;د هغې بندول داسې مشکل وى لکه د هوا بندول او يا تېل په موټى کښې نيول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16196, 'Proverbs 27:17', 'Proverbs', 27, 17, '&nbsp;لکه څنګه چې اوسپنه اوسپنه تيره کوى، نو دغه شان يو انسان بل انسان تېرۀ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16197, 'Proverbs 27:18', 'Proverbs', 27, 18, '&nbsp;کۀ څوک د اينځر د ونې خيال ساتى نو د هغې مېوه به هم وخورى، او هر هغه څوک چې د خپل نېک خيال ساتى نو هغه به عزتمند شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16198, 'Proverbs 27:19', 'Proverbs', 27, 19, '&nbsp;لکه څنګه چې په اوبو کښې مخ ښکارى، نو هم دغه شان د يو انسان زړۀ يو انسان څرګندوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16199, 'Proverbs 27:20', 'Proverbs', 27, 20, '&nbsp;لکه څنګه چې په مرګ او تباهى دُنيا نۀ مړيږى، هم دغه شان د انسان سترګې کله هم نۀ مړيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16200, 'Proverbs 27:21', 'Proverbs', 27, 21, '&nbsp;سپين او سرۀ زر په اور آزمائيلے شى، او يو انسان د هغۀ د صِفت کولو نه وروستو آزمائيلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');